# app.py
from flask import Flask, request, jsonify
import docker
from jinja2 import Template
import subprocess
import tempfile
import os
import shutil

app = Flask(__name__)
client = docker.from_env()

test_template = Template("""
import pytest
from user_code import {{ function_name }}

def test_{{ function_name }}_basic():
    assert {{ function_name }}({{ args }}) == {{ expected }}
""")

@app.route('/generate-tests', methods=['POST'])
def generate_tests():
    data = request.json
    user_code = data.get('code', '')
    function_name = 'add'
    args = '2, 3'
    expected = 5
    
    test_code = test_template.render(function_name=function_name, args=args, expected=expected)
    
    validation = validate_code(test_code)
    if not validation['valid']:
        return jsonify(validation), 400
    
    with tempfile.TemporaryDirectory() as tmpdir:
        user_path = os.path.join(tmpdir, 'user_code.py')
        test_path = os.path.join(tmpdir, 'tests/test_add.py')
        os.makedirs(os.path.dirname(test_path))
        
        with open(user_path, 'w') as f:
            f.write(user_code)
        with open(test_path, 'w') as f:
            f.write(test_code)
            
        try:
            container = client.containers.run(
                'python:3.9-slim',
                command=f'bash -c "pip install pytest && pytest {tmpdir}/tests -v"',
                volumes={tmpdir: {'bind': '/app', 'mode': 'ro'}},
                working_dir='/app',
                stderr=True,
                stdout=True,
                stream=True
            )
            output = ''.join([chunk.decode() for chunk in container])
            return jsonify({
                'test_code': test_code,
                'test_results': output,
                'valid': True
            })
        except Exception as e:
            return jsonify({'error': str(e)}), 500

def validate_code(code):
    with tempfile.NamedTemporaryFile(mode='w', delete=False) as f:
        f.write(code)
        f_path = f.name
    
    try:
        result = subprocess.run(['pylint', f_path], capture_output=True, text=True)
        os.unlink(f_path)
        if result.returncode != 0:
            return {
                'valid': False,
                'error': 'Syntax validation failed',
                'details': result.stdout + result.stderr
            }
        return {'valid': True}
    except Exception as e:
        return {'valid': False, 'error': str(e)}

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=5000)
